cat <<'EOF' > app/javascript/controllers/local_time_controller.js
import { Controller } from "@hotwired/stimulus"
import { differenceInDays, secondsToDate } from "helpers/date_helpers"

const DEFAULT_LOCALE = "en-US"

export default class extends Controller {
  static targets = [ "time", "date", "datetime", "shortdate", "ago", "indays", "daysago", "agoorweekday", "timeordate" ]
  static values = {
    refreshInterval: Number,
    locale: { type: String, default: "en" }
  }
  static classes = [ "local-time-value" ]

  #timer

  initialize() {
    this.#buildFormatters()
  }

  connect() {
    this.#timer = setInterval(() => this.#refreshRelativeTimes(), 30_000)
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  localeValueChanged() {
    if (document.documentElement.lang !== this.localeValue) {
      document.documentElement.lang = this.localeValue
    }
    this.#buildFormatters()
    this.refreshAll()
  }

  refreshAll() {
    this.constructor.targets.forEach(targetName => {
      this.targets.findAll(targetName).forEach(target => {
        this.#formatTime(this[`${targetName}Formatter`], target)
      })
    })
  }

  refreshTarget(event) {
    const target = event.target
    const targetName = target.dataset.localTimeTarget
    this.#formatTime(this[`${targetName}Formatter`], target)
  }

  timeTargetConnected(target) {
    this.#formatTime(this.timeFormatter, target)
  }

  dateTargetConnected(target) {
    this.#formatTime(this.dateFormatter, target)
  }

  datetimeTargetConnected(target) {
    this.#formatTime(this.datetimeFormatter, target)
  }

  shortdateTargetConnected(target) {
    this.#formatTime(this.shortdateFormatter, target)
  }

  agoTargetConnected(target) {
    this.#formatTime(this.agoFormatter, target)
  }

  indaysTargetConnected(target) {
    this.#formatTime(this.indaysFormatter, target)
  }

  daysagoTargetConnected(target) {
    this.#formatTime(this.daysagoFormatter, target)
  }

  agoorweekdayTargetConnected(target) {
    this.#formatTime(this.agoorweekdayFormatter, target)
  }

  timeordateTargetConnected(target) {
    this.#formatTime(this.timeordateFormatter, target)
  }

  #buildFormatters() {
    const locale = this.localeValue
    const intlLocale = locale === "ja" ? "ja-JP" : DEFAULT_LOCALE

    this.timeFormatter = new Intl.DateTimeFormat(intlLocale, { timeStyle: "short" })
    this.dateFormatter = new Intl.DateTimeFormat(intlLocale, { dateStyle: "long" })
    this.shortdateFormatter = new Intl.DateTimeFormat(intlLocale, { month: "short", day: "numeric" })
    this.datetimeFormatter = new Intl.DateTimeFormat(intlLocale, { timeStyle: "short", dateStyle: "short" })
    this.agoFormatter = new AgoFormatter(locale)
    this.daysagoFormatter = new DaysAgoFormatter(locale)
    this.datewithweekdayFormatter = new Intl.DateTimeFormat(intlLocale, { weekday: "long", month: "long", day: "numeric" })
    this.indaysFormatter = new InDaysFormatter(locale)
    this.agoorweekdayFormatter = new DaysAgoOrWeekdayFormatter(locale, intlLocale)
    this.timeordateFormatter = new TimeOrDateFormatter(intlLocale)
  }

  #refreshRelativeTimes() {
    this.agoTargets.forEach(target => {
      this.#formatTime(this.agoFormatter, target)
    })
  }

  #formatTime(formatter, target) {
    const dt = secondsToDate(parseInt(target.getAttribute("datetime")))
    target.innerHTML = formatter.format(dt)
    target.title = this.datetimeFormatter.format(dt)
  }
}

class AgoFormatter {
  constructor(locale = "en") {
    this.locale = locale
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#pluralize("year", years)
    if (months >= 1) return this.#pluralize("month", months)
    if (weeks >= 1) return this.#pluralize("week", weeks)
    if (days >= 1) return this.#pluralize("day", days)
    if (hours >= 1) return this.#pluralize("hour", hours)
    if (minutes >= 1) return this.#pluralize("minute", minutes)

    return this.locale === "ja" ? "1分未満前" : "Less than a minute ago"
  }

  #pluralize(unit, quantity) {
    quantity = Math.floor(quantity)
    if (this.locale === "ja") {
      const units = { year: "年", month: "か月", week: "週間", day: "日", hour: "時間", minute: "分" }
      return `${quantity}${units[unit]}前`
    } else {
      const suffix = (quantity === 1) ? "" : "s"
      return `${quantity} ${unit}${suffix} ago`
    }
  }
}

class DaysAgoFormatter {
  constructor(locale = "en") {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (this.locale === "ja") {
      if (days <= 0) return styleableValue("今日")
      if (days === 1) return styleableValue("昨日")
      return `${styleableValue(days)}日前`
    } else {
      if (days <= 0) return styleableValue("today")
      if (days === 1) return styleableValue("yesterday")
      return `${styleableValue(days)} days ago`
    }
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale = "en", intlLocale = DEFAULT_LOCALE) {
    this.locale = locale
    this.intlLocale = intlLocale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter(this.locale).format(date)
    } else {
      return new Intl.DateTimeFormat(this.intlLocale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  constructor(locale = "en") {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(new Date(), date)

    if (this.locale === "ja") {
      if (days <= 0) return styleableValue("今日")
      if (days === 1) return styleableValue("明日")
      return `${styleableValue(days)}日後`
    } else {
      if (days <= 0) return styleableValue("today")
      if (days === 1) return styleableValue("tomorrow")
      return `in ${styleableValue(days)} days`
    }
  }
}

class TimeOrDateFormatter {
  constructor(intlLocale = DEFAULT_LOCALE) {
    this.intlLocale = intlLocale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(this.intlLocale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(this.intlLocale, { timeStyle: "short" }).format(date)
    }
  }
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
EOF

cat <<'EOF' > app/javascript/controllers/bubble_controller.js
import { Controller } from "@hotwired/stimulus"
import { signedDifferenceInDays } from "helpers/date_helpers"

const REFRESH_INTERVAL = 3_600_000 // 1 hour (in milliseconds)

export default class extends Controller {
  static targets = [ "entropy", "stalled", "top", "center", "bottom" ]
  static values = { entropy: Object, stalled: Object }

  #timer

  connect() {
    this.#timer = setInterval(this.update.bind(this), REFRESH_INTERVAL)
    this.update()
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  update() {
    if (this.#hasEntropy) {
      this.#showEntropy()
    } else if (this.#isStalled) {
      this.#showStalled()
    } else {
      this.#hide()
    }
  }

  get #hasEntropy() {
    return this.#entropyCleanupInDays < this.entropyValue.daysBeforeReminder
  }

  get #entropyCleanupInDays() {
    return signedDifferenceInDays(new Date(), new Date(this.entropyValue.closesAt))
  }

  #showEntropy() {
    const days = this.#entropyCleanupInDays
    this.#render({
      top: days < 1 ? this.entropyValue.action : (this.entropyValue.actionIn || `${this.entropyValue.action} in`),
      center: days < 1 ? "!" : days,
      bottom: days < 1 ? (this.entropyValue.today || "Today") : (days === 1 ? (this.entropyValue.day || "day") : (this.entropyValue.days || "days")),
    })
  }

  #render({ top, center, bottom }) {
    this.topTarget.innerHTML = top
    this.centerTarget.innerHTML = center
    this.bottomTarget.innerHTML = bottom

    this.#show()
  }

  // Keep in sync with Card::Stallable#stalled? in app/models/card/stallable.rb
  get #isStalled() {
    return this.stalledValue.lastActivitySpikeAt &&
      signedDifferenceInDays(new Date(this.stalledValue.lastActivitySpikeAt), new Date()) > this.stalledValue.stalledAfterDays &&
      signedDifferenceInDays(new Date(this.stalledValue.updatedAt), new Date()) > this.stalledValue.stalledAfterDays
  }

  #showStalled() {
    this.#render({
      top: this.stalledValue.stalledFor || "Stalled for",
      center: signedDifferenceInDays(new Date(this.stalledValue.lastActivitySpikeAt), new Date()),
      bottom: this.stalledValue.days || "days"
    })
  }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

  #show() {
    this.element.removeAttribute("hidden")
  }
}
EOF

cat <<'EOF' > app/javascript/controllers/turbo_navigation_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = {
    label: String,
    backTemplate: { type: String, default: "Back to %{label}" }
  }
  static targets = [ "referrerBackLink" ]

  rememberLocation() {
    sessionStorage.setItem("referrerUrl", window.location.href)
    sessionStorage.setItem("referrerLabel", this.labelValue)
  }

  backIfSamePath(event) {
    if (event.ctrlKey || event.metaKey || event.shiftKey) { return }

    const link = event.target.closest("a")
    const targetUrl = new URL(link.href)

    if (this.#referrerPath && targetUrl.pathname === this.#referrerPath) {
      event.preventDefault()
      Turbo.visit(this.#referrerUrl)
    }
  }

  referrerBackLinkTargetConnected(link) {
    if (!this.#referrerUrl || !this.#referrerLabel) { return }

    const stripTrailingSlash = path => path.replace(/\/$/, "")
    const allowedPaths = (link.dataset.turboNavigationAllowedReferrerPaths || "").split(",").map(stripTrailingSlash)
    const referrerPath = stripTrailingSlash(new URL(this.#referrerUrl).pathname)
    if (!allowedPaths.includes(referrerPath)) { return }

    link.href = this.#referrerUrl
    const strong = link.querySelector("strong")
    if (strong) { strong.textContent = this.backTemplateValue.replace("%{label}", this.#referrerLabel) }
  }

  get #referrerPath() {
    if (!this.#referrerUrl) return null
    return new URL(this.#referrerUrl).pathname
  }

  get #referrerUrl() {
    return sessionStorage.getItem("referrerUrl")
  }

  get #referrerLabel() {
    return sessionStorage.getItem("referrerLabel")
  }
}
EOF

