        selectPropertyName: { type: String, default: "aria-checked" },
        defaultValue: String,
        noSelectionLabel: { type: String, default: "No selection" },
        labelPrefix: String,
        labelJoiner: { type: String, default: " " },
        wordsConnector: { type: String, default: ", " },
        twoWordsConnector: { type: String, default: " or " },
        lastWordConnector: { type: String, default: ", or " }
      }
  CODE
)
content.sub!(
  /    const sentence = toSentence\(labels, \{\n      two_words_connector: " or ",\n      last_word_connector: ", or "\n    \}\)\n\n    return this\.hasLabelPrefixValue \? `\$\{this\.labelPrefixValue\} \$\{sentence\}` : sentence/,
  <<~'CODE'.chomp
        const sentence = toSentence(labels, {
          words_connector: this.wordsConnectorValue,
          two_words_connector: this.twoWordsConnectorValue,
          last_word_connector: this.lastWordConnectorValue
        })

        return this.hasLabelPrefixValue && this.labelPrefixValue ? `${this.labelPrefixValue}${this.labelJoinerValue}${sentence}` : sentence
  CODE
)
